-- =====================================================================
-- Nuovo set Pokémon: 30° Anniversario (TCGdex 30th, uscita 16/09/2026)
-- 161 carte (carte con lettera B/G/R -> number 900+posizione lettera, number_label = lettera).
-- Nuove rarità: Pikachu Rare, Futuristic Rare, RGB Rare.
-- Colori dalla galleria ufficiale tcg.pokemon.com/galleries/30th-celebration.
-- Idempotente (UUID deterministici, uguali a quelli di `npm run catalog:sync`).
-- =====================================================================

-- 1) Rarità della collezione Pokémon (ordine + nomi italiani) e ricalcolo dei rank
update public.tcg_collections
set rarity_order = '{Comune,Non comune,Rara,Rara doppia,Ultrarara,Rara illustrazione,Pikachu Rare,Rara illustrazione speciale,Futuristic Rare,RGB Rare,Rara iper Mega,Mega Iper Raro}',
    rarity_labels = rarity_labels || '{"Pikachu Rare": "Rara Pikachu", "Futuristic Rare": "Rara futuristica", "RGB Rare": "Rara RGB"}'::jsonb
where id = 'pokemon-tcg';

update public.tcg_cards c
set rarity_rank = coalesce(array_position(
      (select array_agg(upper(x) order by i) from unnest(col.rarity_order) with ordinality as t(x, i)),
      upper(c.rarity)), 99)
from public.tcg_sets s
join public.tcg_collections col on col.id = s.collection_id
where s.id = c.set_id and col.id = 'pokemon-tcg';

-- 2) Set
values ('pokemon-30th', 'pokemon-tcg', '30° Anniversario', 'Megaevoluzione', '30TH', '2026-09-16', 'tcgdex',
        '{"setId":"30th","series":"me","lang":"it","syncRarity":true}', '{"accent": "#F9DB30", "accent2": "#8AE0FE", "ink": "#FFF9E6", "bg": "#12001C", "bg2": "#4B0064", "glow": "rgba(249,219,48,0.40)", "pattern": "stars"}', 30)
on conflict (id) do update set
  name = excluded.name, subtitle = excluded.subtitle, code = excluded.code, release_date = excluded.release_date,
  price_provider = excluded.price_provider, price_config = excluded.price_config, theme = excluded.theme, sort = excluded.sort;

-- 3) Carte
on conflict (id) do update set
  number_label = excluded.number_label, name = excluded.name, rarity = excluded.rarity, rarity_rank = excluded.rarity_rank,
  version = excluded.version, type = excluded.type, image_url = excluded.image_url, external_id = excluded.external_id;

select set_id, count(*) as carte, count(*) filter (where version = 'Holo') as holo,
       min(rarity_rank) as rank_min, max(rarity_rank) as rank_max
from public.tcg_cards where set_id like 'pokemon-%' group by set_id order by set_id;
